
// ==========================================================================
// مِرصاد — واجهة التطبيق
// طبقة العرض والتفاعل. منطق الربط مع Supabase والـ API في الجزء الثاني من الملف.
// اللغة: العربية افتراضيًا، مع تبديل كامل إلى الإنجليزية (LTR) — القاموس في public/mirsad-i18n.js
// ==========================================================================

// ---------- اللغة / Language ----------
// النصوص العربية هي المفاتيح. tr() تعيد الترجمة الإنجليزية عند اختيار English، وإلا النص العربي كما هو.
let lang=(()=>{try{return localStorage.getItem('mirsad-lang')==='en'?'en':'ar'}catch{return 'ar'}})();
function dict(){try{return (typeof window!=='undefined'&&window.MirsadEN)||{}}catch{return {}}}
function tr(s,vars){let out=String(s??'');if(lang==='en'){const d=dict();if(Object.hasOwn(d,out))out=d[out]}return vars?out.replace(/\{(\w+)\}/g,(m,k)=>Object.hasOwn(vars,k)?String(vars[k]):m):out}
function locale(){return lang==='en'?'en-GB':'ar-SA'}
function plural(n,ar,en){return lang==='en'?`${n} ${n===1?en[0]:en[1]}`:`${n} ${ar}`}
// رسائل أخطاء الخادم حسب الرمز، لعرضها بالإنجليزية.
const errorsEN={PRIORITY_REVIEW_REQUIRED:'Manual priority is only available for tickets awaiting technician review.',AUTH_REQUIRED:'Sign in to continue.',NOT_ALLOWED:'You do not have access to this ticket.',TECH_REQUIRED:'This action is for approved technicians only.',OWNER_REQUIRED:'Only the assigned technician can do this.',NOT_RECIPIENT:'Only the receiving technician can accept or decline the handover.',ADMIN_REQUIRED:'This action requires administrator access.',CONFLICT:'The ticket changed. Refresh the page and try again.',INVALID_INPUT:'Check the required fields and text length.',INVALID_RECIPIENT:'Choose another approved technician.',REASON_REQUIRED:'Write a reason for declining.',REVIEW_REQUIRED:'Review the details and confirm you are ready to take over.',HANDOVER_PENDING:'A handover request is pending. Resolve it first.',TASKS_REMAIN:'Complete the remaining steps before closing the ticket.',TICKET_CLOSED:'The ticket is closed.',AI_BUSY:'The ticket is being analysed. Refresh in a moment.',RATE_LIMIT:'You have reached the attempt limit. Wait a moment and try again.',NOT_FOUND:'The requested item was not found.',NOT_CONFIGURED:'The services are not connected yet.',AI_NOT_CONFIGURED:'The AI service is not connected yet.',DATA_UNAVAILABLE:'Could not complete the request. Please try again.',SERVICE_UNAVAILABLE:'Could not reach the service. Your submitted data will not be replaced by a test result.'};
// رسائل السجل التي تكتبها قاعدة البيانات بالعربية — تُترجم عند العرض فقط.
const eventPatterns=[
 [/^رفض الاستلام\. السبب: ([\s\S]*)\. يبقى الفني السابق مسؤولًا\.$/,'Handover declined. Reason: {1}. The previous technician remains responsible.'],
 [/^أضيفت خطوة: ([\s\S]*)$/,'Step added: {1}'],
 [/^اكتملت خطوة: ([\s\S]*)$/,'Step completed: {1}'],
 [/^أعيد فتح خطوة: ([\s\S]*)$/,'Step reopened: {1}'],
 [/^أرسل طلب تسليم إلى ([\s\S]*)\. المسؤولية لا تنتقل قبل القبول\.$/,'Handover request sent to {1}. Responsibility does not move until it is accepted.'],
 [/^أحيلت الأولوية لمراجعة الفنيين: ([\s\S]*)$/,'Priority referred to technician review: {1}'],
 [/^حدد الذكاء الاصطناعي الأولوية\. السبب: ([\s\S]*)$/,'AI set the priority. Reason: {1}'],
 [/^حدد الفني الأولوية: (عالية|متوسطة|منخفضة)\. السبب: ([\s\S]*)$/,'Technician set the priority: {1}. Reason: {2}']
];
function trEvent(m){m=String(m??'');if(lang!=='en')return m;if(Object.hasOwn(dict(),m))return tr(m);for(const [re,out] of eventPatterns){const x=m.match(re);if(x)return out.replace(/\{(\d)\}/g,(_,i)=>tr(x[i]))}return m}

