// الأسهم تنعكس تلقائيًا في الواجهة الإنجليزية (LTR).
const icon=(n)=>{if(lang==='en'&&(n==='arrow'||n==='back'))n=n==='arrow'?'back':'arrow';return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.ticket}"/></svg>`};
// عين الشعار المتحركة: رادار يدور وإشارة كهرمانية تنبض.
const eye=()=>`<svg class="eye" viewBox="-6 -16 532 300" aria-hidden="true"><g class="lidshape"><path class="lid" d="M14 135Q259 -100 504 135Q259 370 14 135Z"/><g class="radar"><path class="sweep" d="M259 135L259 41A94 94 0 0 1 332 76Z"/><line class="needle" x1="259" y1="135" x2="334" y2="78"/></g><circle class="iris" cx="259" cy="135" r="108"/><circle class="pupil" cx="259" cy="135" r="24"/></g><circle class="gap" cx="381" cy="50" r="46"/><circle class="halo" cx="381" cy="50" r="32"/><circle class="signal" cx="381" cy="50" r="32"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs={dashboard:['grid','لوحة التحكم'],tickets:['ticket','قائمة البلاغات'],handovers:['swap','تسليم المهام'],tasks:['check','مهامي'],activity:['clock','سجل النشاط']};
const seed=()=>({tickets:[],drafts:{},nextId:1});
let db=seed();let page='dashboard',selected=1,filter={q:'',status:'',priority:'',sort:'new'},toastTimer,modalReturn;
let lastViewKey=null,enterTimer=null,closeTimer=null,lastStatus=null,lastPending=null,lastBellDot=null,initialRoute=null,routeApplied=false;
function save(){}
const ticket=()=>db.tickets.find(t=>t.id===selected)||db.tickets[0];
const now=()=>new Intl.DateTimeFormat(locale(),{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Riyadh'}).format(new Date());
function log(t,text){t.logs.unshift({text,time:now(),at:Date.now()})}
function reducedMotion(){return typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches}
function initials(s){return String(s||'').split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('')}
// "منذ ٥ دقائق" / "5 minutes ago"
function ago(ms){if(!ms||!Number.isFinite(ms))return '';const s=Math.round((ms-Date.now())/1000),a=Math.abs(s);if(a<45)return tr('الآن');const rtf=new Intl.RelativeTimeFormat(lang==='en'?'en':'ar',{numeric:'auto'});if(a<3600)return rtf.format(Math.round(s/60),'minute');if(a<86400)return rtf.format(Math.round(s/3600),'hour');if(a<604800)return rtf.format(Math.round(s/86400),'day');return new Intl.DateTimeFormat(locale(),{dateStyle:'medium',timeZone:'Asia/Riyadh'}).format(new Date(ms))}
function greeting(){let h=12;try{h=Number(new Intl.DateTimeFormat('en-GB',{hour:'numeric',hourCycle:'h23',timeZone:'Asia/Riyadh'}).format(new Date()))}catch{}return tr(h<12?'صباح الخير':'مساء الخير')}

// ---------- Toasts ----------
function toast(s,type='success'){
  const box=document.getElementById('toasts');if(!box)return;
  while(box.children.length>=4)box.firstElementChild.remove();
  const el=document.createElement('div');el.className='toast '+type;
  el.innerHTML=`<span class="ti">${icon(type==='error'?'warn':type==='info'?'info':'check')}</span><p>${esc(s)}</p><button class="tx" aria-label="${esc(tr('إغلاق التنبيه'))}">${icon('close')}</button><span class="tbar"></span>`;
  const dismiss=()=>{if(el.classList.contains('out'))return;el.classList.add('out');setTimeout(()=>el.remove(),340)};
  let timer=setTimeout(dismiss,3800);
  el.addEventListener('mouseenter',()=>clearTimeout(timer));
  el.addEventListener('mouseleave',()=>{timer=setTimeout(dismiss,1600)});
  el.querySelector('.tx').onclick=dismiss;
  box.appendChild(el);
}

function toggleMenu(open){const e=document.getElementById('sidebar');const v=open??!e.classList.contains('open');e.classList.toggle('open',v);document.getElementById('overlay').classList.toggle('open',v)}
function toggleTheme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('mirsad-theme',next)}catch{}}

// ---------- تبديل اللغة ----------
function applyLanguage(){
  const root=document.documentElement;root.lang=lang;root.dir=lang==='en'?'ltr':'rtl';
  document.title=tr('مِرصاد — منصة الدعم الفني');
  document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=tr(el.dataset.i18n)});
  document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',tr(el.dataset.i18nAria)));
  const b=document.getElementById('langToggle');if(b){b.innerHTML=`<span class="lang-code">${lang==='en'?'ع':'EN'}</span>`;b.setAttribute('aria-label',lang==='en'?'التبديل إلى العربية':'Switch to English');b.title=lang==='en'?'العربية':'English'}
  const th=document.getElementById('themeToggle');if(th)th.setAttribute('aria-label',tr('تبديل الوضع الليلي'));
}
function toggleLang(){lang=lang==='en'?'ar':'en';try{localStorage.setItem('mirsad-lang',lang)}catch{}applyLanguage();lastStatus=null;document.getElementById('accountActions').dataset.html='';document.getElementById('sideAccount').dataset.html='';const d=document.getElementById('modal');if(d.open)closeModal();render();toast(lang==='en'?'Interface switched to English.':'تم التبديل إلى العربية.','info')}

// ---------- Badges & people ----------
const badgeTone={'عالية':'red hot','متوسطة':'amber','منخفضة':'green','مكتمل':'green','مقبول':'green','مرفوض':'red','بانتظار الاستلام':'amber','معلّق':'amber','قيد العمل':'blue','جديد':'violet','بانتظار مراجعة فني':'review','جارٍ التحليل':'ai','بانتظار التصنيف':'violet'};
function badge(s){return `<span class="badge ${badgeTone[s]||''}"><i class="bd"></i>${esc(tr(s))}</span>`}
function person(s){const none=s==='بانتظار الإسناد';const name=tr(s);return `<span class="person"><span class="miniavatar ${none?'none':''}">${none?'?':esc(initials(name))}</span>${esc(name)}</span>`}
function openTicket(id){const t=db.tickets.find(t=>t.id===id);if(!canView(t))return toast(tr('هذا البلاغ غير متاح لحسابك.'),'error');selected=id;go('details')}
function go(p,opts={}){if(['handovers','handover','review','success','tasks','activity','notifications'].includes(p)&&!isTech()){if(opts.silent){p='dashboard'}else{if(!currentUser())return openAuth('login','tech');return toast(tr('هذه الصفحة مخصصة للفنيين.'),'info')}}if(p==='details'&&!canView(ticket()))p='tickets';page=p;toggleMenu(false);if(opts.push!==false)pushRoute();render();window.scrollTo({top:0,behavior:'instant'})}
function heading(title,sub,action='',eyebrow='MIRSAD / IT SUPPORT'){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action?`<div class="headactions">${action}</div>`:''}</div>`}
const newTicketLabel=()=>tr(isTech()?'تسجيل بلاغ':'إنشاء بلاغ');
const newbtn=()=>`<button class="btn" onclick="openNew()">${icon('plus')}${newTicketLabel()}<kbd class="kbd-hint">N</kbd></button>`;
function panelTitle(ic,text){return `<h2><span class="chip">${icon(ic)}</span>${text}</h2>`}

// ---------- روابط مباشرة (#/details/12) وزر الرجوع في المتصفح ----------
const routablePages=['dashboard','tickets','details','handover','handovers','review','tasks','activity','notifications'];
function routeHash(){const p=page==='success'?'details':page;return ['details','handover','review'].includes(p)?`#/${p}/${selected}`:`#/${p}`}
function parseRoute(h){const m=String(h||'').match(/^#\/([a-z]+)(?:\/(\d+))?$/);if(!m||!routablePages.includes(m[1]))return null;return {page:m[1],id:m[2]?Number(m[2]):null}}
function pushRoute(){try{const h=routeHash();if(location.hash!==h)history.pushState(null,'',h)}catch{}}
function syncRoute(){if(!routeApplied)return;try{const h=routeHash();if(location.hash!==h)history.replaceState(null,'',h)}catch{}}
function applyRoute(r){if(!r)return;if(r.id&&db.tickets.some(t=>t.id===r.id))selected=r.id;else if(['details','handover','review'].includes(r.page))return go('tickets',{push:false,silent:true});go(r.page,{push:false,silent:true})}

// ---------- Tickets table ----------
function rows(ts){return ts.length?ts.map(t=>`<tr onclick="openTicket(${t.id})"><td><span class="refchip">${ticketRef(t.id)}</span></td><td><button class="tickettitle" onclick="event.stopPropagation();openTicket(${t.id})">${esc(t.title)}</button><div class="ticketmeta">${icon('tag')}${esc(tr(t.category))} <span aria-hidden="true">·</span> ${icon('pin')}${esc(t.place)}${t.createdAt?` <span aria-hidden="true">·</span> <span title="${esc(formatTime(t.createdAt))}">${icon('clock')}${esc(ago(t.createdAt))}</span>`:''}</div></td><td>${badge(t.priority)}${badge(t.status)}</td><td>${badge(t.status)}</td><td>${person(t.owner)}</td><td><button class="iconbtn rowgo" aria-label="${esc(tr('فتح البلاغ {id}',{id:formatId(t.id)}))}" onclick="event.stopPropagation();openTicket(${t.id})">${icon('arrow')}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${icon('search')}<p>${tr('لا توجد بلاغات تطابق البحث.')}</p></div></td></tr>`}
function table(ts){return `<div class="tablewrap"><table><thead><tr><th>${tr('رقم البلاغ')}</th><th>${tr('البلاغ')}</th><th>${tr('الأولوية')}</th><th>${tr('الحالة')}</th><th>${tr('المسؤول')}</th><th><span class="sr">${tr('فتح')}</span></th></tr></thead><tbody id="ticketrows">${rows(ts)}</tbody></table></div>`}
function tasklist(t,interactive=true){interactive=interactive&&isTech()&&t.ownerId===currentUser()?.id&&t.status!=='بانتظار الاستلام';if(!t.tasks.length)return `<p class="muted" style="font-size:12.5px">${tr('لا توجد خطوات مسجلة بعد.')}</p>`;return t.tasks.map((x,i)=>`<div class="taskitem"><input type="checkbox" id="task-${formatId(t.id)}-${i}" ${x.done?'checked':''} ${interactive?'':'disabled'} onchange="setTask(${t.id},${i},this.checked)"><label for="task-${formatId(t.id)}-${i}"><span>${esc(tr(x.text))}</span><small>${tr('بلاغ')} ${ticketRef(t.id)}</small></label></div>`).join('')}
function progressRing(done,total){const p=total?done/total:0,C=2*Math.PI*22;return `<div class="ring ${total&&done===total?'full':''}" title="${esc(tr('{done} من {total}',{done,total}))}"><svg viewBox="0 0 54 54"><circle class="track" cx="27" cy="27" r="22"/><circle class="val" cx="27" cy="27" r="22" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${(C*(1-p)).toFixed(1)}"/></svg><b>${Math.round(p*100)}%</b></div>`}
function statCard([label,value,note,ic,tone,onclick]){return `<div class="stat ${tone} ${onclick?'clickable':''}" ${onclick?`role="button" tabindex="0" onclick="${onclick}" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();${onclick}}"`:''}><div class="statlabel">${label}<span class="chip">${icon(ic)}</span></div><div class="statval" data-count="${value}">${String(value).padStart(2,'0')}</div><div class="statnote">${note}</div></div>`}
function ticketsCount(n){if(lang==='en')return plural(n,'',['ticket','tickets']);return n===1?'بلاغ واحد':n===2?'بلاغان':n>=3&&n<=10?`${n} بلاغات`:`${n} بلاغ`}

// ---------- Pages ----------
function dashboard(){
  const u=currentUser(),ts=visibleTickets(),active=ts.filter(t=>t.status!=='مكتمل'),urgent=active.filter(t=>t.priority==='عالية'),pending=ts.filter(t=>t.handover?.state==='pending'),remaining=ts.flatMap(t=>t.tasks).filter(x=>!x.done).length,closed=ts.length-active.length;const t=active[0];
  const title=tr(isTech()?'نظرة على سير العمل':u?'متابعة بلاغاتك':'مرحبًا بك في مرصاد');
  const sub=tr(isTech()?'تابع البلاغات، وثّق الإجراءات، وسلّم العمل بوضوح.':'بلّغ عن المشكلة، وتابع تقدم الحل من مكان واحد.');
  const second=isTech()?`<button class="btn ghost" onclick="go('handovers')">${icon('swap')}${tr('تسليم المهام')}</button>`:u?`<button class="btn ghost" onclick="go('tickets')">${icon('ticket')}${tr('بلاغاتي')}</button>`:`<button class="btn ghost" onclick="openAuth('login','tech')">${icon('wrench')}${tr('دخول الفنيين')}</button>`;
  const hero=`<section class="hero"><div><div class="eyebrow">${u?esc(greeting()+tr('، ')+u.name.split(' ')[0]):'MIRSAD · IT SUPPORT'}</div><h1>${title}</h1><p class="subtitle">${sub}</p><div class="hero-actions">${newbtn()}${second}</div><div class="hero-meta"><span><span class="sig on"></span>${tr('تصنيف أولوية بالذكاء الاصطناعي')}</span><span>${icon('shield')}${tr('صلاحيات محمية لكل حساب')}</span>${ts.length?`<span>${icon('check')}${tr('المكتملة: {n}',{n:closed})}</span>`:''}</div></div><div class="hero-eye">${eye()}</div></section>`;
  const stats=`<div class="stats">${[[tr('البلاغات النشطة'),active.length,tr('بلاغات تحتاج إلى متابعة'),'ticket','',u?"quickFilter('','')":''],[tr('أولوية عالية'),urgent.length,urgent.length?'<span class="sig off"></span>'+tr('تحتاج تدخلًا سريعًا'):tr('تصنيف تلقائي للمشكلات'),'warn','urgent',u?"quickFilter('','عالية')":''],[tr('بانتظار الاستلام'),pending.length,(pending.length?'<span class="sig wait"></span>':'')+tr('طلبات تسليم معلّقة'),'swap','wait',isTech()?"go('handovers')":u?"quickFilter('بانتظار الاستلام','')":''],[tr('خطوات متبقية'),remaining,tr('إجراءات تحتاج إلى استكمال'),'check','done',isTech()?"go('tasks')":'']].map(statCard).join('')}</div>`;
  if(!ts.length)return hero+stats+`<section class="panel emptyhero"><div class="bigeye">${eye()}</div><div class="guesttag"><span class="sig ${u?'on':'wait'}"></span>${tr(u?'مساحة عملك جاهزة':'مساران واضحان: مستخدم وفني')}</div><h2>${tr(isTech()?'ابدأ باستقبال البلاغات ومتابعتها':'أول خطوة للحل تبدأ ببلاغ واضح')}</h2><p>${tr(u?'لا توجد بلاغات لعرضها حتى الآن. يمكنك إنشاء بلاغ جديد.':'سجّل الدخول أو أنشئ حسابًا لإرسال المشكلة ومتابعة حالتها.')}</p><div class="btns">${u?newbtn():`<button class="btn" onclick="openAuth('signup','user')">${icon('user')}${tr('إنشاء حساب مستخدم')}</button><button class="btn secondary" onclick="openAuth('login','tech')">${icon('wrench')}${tr('دخول الفنيين')}</button>`}</div><div class="howto"><div><span class="step">1</span><strong>${tr('صف المشكلة')}</strong><small>${tr('عنوان واضح وتفاصيل وخمسة أسئلة سريعة.')}</small></div><div><span class="step">2</span><strong>${tr('تحليل الأولوية')}</strong><small>${tr('يحدد الذكاء الاصطناعي الأولوية ويشرح السبب.')}</small></div><div><span class="step">3</span><strong>${tr('تابع الحل')}</strong><small>${tr('خطوات وسجل كامل حتى إغلاق البلاغ.')}</small></div></div></section>`;
  const u0=urgent[0];
  const banner=u0?`<div class="urgentbanner"><div class="ub-main"><span class="ub-icon">${icon('warn')}</span><div style="min-width:0"><div class="badges"><span class="refchip">${ticketRef(u0.id)}</span>${badge('عالية')}${urgent.length>1?`<span class="endtag">${tr('+{n} أخرى',{n:urgent.length-1})}</span>`:''}</div><h3>${esc(u0.title)}</h3></div></div><button class="btn sm danger" onclick="openTicket(${u0.id})">${tr('متابعة البلاغ')} ${icon('arrow')}</button></div>`:'';
  const counts=[['عالية',urgent.length,'var(--red)'],['متوسطة',active.filter(x=>x.priority==='متوسطة').length,'var(--amber)'],['منخفضة',active.filter(x=>x.priority==='منخفضة').length,'var(--green)'],['بانتظار مراجعة',active.filter(x=>!['عالية','متوسطة','منخفضة'].includes(x.priority)).length,'var(--brand)']];const max=Math.max(1,...counts.map(c=>c[1]));
  const dist=`<section class="panel"><div class="panelhead">${panelTitle('chart',tr('توزيع الأولويات'))}<span class="badge violet"><i class="bd"></i>AI</span></div><div class="panelbody"><div class="dist">${counts.map(([l,n,c])=>`<div class="distrow" style="--c:${c}"><span class="lbl"><i></i>${tr(l)}</span><div class="bar"><span style="width:${n/max*100}%"></span></div><b>${n}</b></div>`).join('')}</div><p class="description" style="font-size:12px;margin-top:16px;line-height:1.9">${tr('اكتب المشكلة وتأثيرها على العمل بوضوح، وسيظهر تصنيف الأولوية وسببه في تفاصيل البلاغ.')}</p></div></section>`;
  const next=`<section class="panel"><div class="panelhead">${panelTitle('flag',tr('الخطوة التالية'))}${t?progressRing(t.tasks.filter(x=>x.done).length,t.tasks.length):''}</div><div class="panelbody">${t?`<h3>${esc(t.title)}</h3><p class="subtitle" style="margin-bottom:14px">${tr('بلاغ')} ${ticketRef(t.id)}</p>${tasklist(t,isTech())}<button class="linkbtn sectionspace" onclick="openTicket(${t.id})">${tr('عرض التفاصيل')} ${icon('arrow')}</button>`:`<div class="empty" style="padding:24px 0">${icon('check')}<p>${tr('جميع البلاغات مكتملة.')}</p></div>`}</div></section>`;
  const logs=ts.flatMap(t=>t.logs.map(l=>({...l,id:formatId(t.id)}))).sort((a,b)=>(b.at||0)-(a.at||0)).slice(0,5);
  return hero+banner+stats+`<div class="layout"><div><section class="panel"><div class="panelhead">${panelTitle('ticket',tr(isTech()?'البلاغات الأخيرة':'بلاغاتي'))}<button class="linkbtn" onclick="go('tickets')">${tr('عرض الكل')} ${icon('arrow')}</button></div>${table(ts.slice(0,5))}<div class="listfoot"><span>${ticketsCount(ts.length)}</span><span class="live"><span class="sig on"></span>${tr('تحديث مباشر')}</span></div></section><section class="panel"><div class="panelhead">${panelTitle('clock',tr('آخر الإجراءات'))}${isTech()?`<button class="linkbtn" onclick="go('activity')">${tr('السجل الكامل')} ${icon('arrow')}</button>`:''}</div><div class="panelbody">${events(logs)}</div></section></div><div class="asidecards">${next}${dist}</div></div>`;
}
const statusOptions=['جديد','قيد العمل','بانتظار الاستلام','مكتمل'];
const priorityOptions=['عالية','متوسطة','منخفضة','بانتظار مراجعة فني'];
function quickFilter(status,priority){filter={q:'',status,priority,sort:filter.sort||'new'};go('tickets')}
function statusChips(){const base=visibleTickets().filter(t=>matchesQuery(t)&&(!filter.priority||t.priority===filter.priority));return `<div class="chips" role="group" aria-label="${esc(tr('تصفية الحالة'))}">${[['',tr('الكل'),base.length],...statusOptions.map(s=>[s,tr(s),base.filter(t=>t.status===s).length])].map(([v,l,n])=>`<button type="button" class="fchip ${filter.status===v?'active':''}" aria-pressed="${filter.status===v}" onclick="filter.status='${v}';updateRows()">${esc(l)}<b>${n}</b></button>`).join('')}</div>`}
function tickets(){const actions=`${isTech()?`<button class="btn secondary" onclick="exportCSV()">${icon('download')}${tr('تصدير CSV')}</button>`:''}${newbtn()}`;return heading(tr(isTech()?'قائمة البلاغات':'بلاغاتي'),tr('ابحث عن البلاغ، تابع حالته، واعرف المسؤول عن الخطوة التالية.'),actions)+`<section class="panel"><div id="statusChips" class="chipbar">${statusChips()}</div><div class="filters"><div class="search">${icon('search')}<input id="search" type="search" aria-label="${esc(tr('البحث في البلاغات'))}" placeholder="${esc(tr('ابحث برقم البلاغ أو العنوان أو اسم الفني…'))}" value="${esc(filter.q)}" oninput="filter.q=this.value;updateRows()"><kbd>/</kbd></div><select aria-label="${esc(tr('تصفية الأولوية'))}" onchange="filter.priority=this.value;updateRows()"><option value="">${tr('كل الأولويات')}</option>${priorityOptions.map(x=>`<option value="${x}" ${filter.priority===x?'selected':''}>${tr(x)}</option>`).join('')}</select><select aria-label="${esc(tr('ترتيب البلاغات'))}" onchange="filter.sort=this.value;updateRows()">${[['new','الأحدث أولًا'],['old','الأقدم أولًا'],['priority','الأعلى أولوية'],['status','حسب الحالة']].map(([v,l])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${tr(l)}</option>`).join('')}</select><button class="btn secondary sm" onclick="filter={q:'',status:'',priority:'',sort:'new'};render()">${icon('close')}${tr('مسح')}</button></div>${table(filtered())}<div class="listfoot"><span id="resultsCount">${ticketsCount(filtered().length)}</span><span class="live"><span class="sig on"></span>${tr('جميع النتائج')}</span></div></section>`}
function matchesQuery(t){const q=filter.q.trim().toLowerCase();if(!q)return true;return `${formatId(t.id)} #${formatId(t.id)} ${t.title} ${tr(t.owner)} ${t.owner} ${t.category} ${tr(t.category)} ${t.place}`.toLowerCase().includes(q)}
const priorityRank={'عالية':0,'بانتظار مراجعة فني':1,'جارٍ التحليل':2,'بانتظار التصنيف':2,'متوسطة':3,'منخفضة':4};
const statusRank={'جديد':0,'قيد العمل':1,'بانتظار الاستلام':2,'مكتمل':3};
function filtered(){const list=visibleTickets().filter(t=>(!filter.status||t.status===filter.status)&&(!filter.priority||t.priority===filter.priority)&&matchesQuery(t));const s=filter.sort||'new';const by={new:(a,b)=>b.id-a.id,old:(a,b)=>a.id-b.id,priority:(a,b)=>(priorityRank[a.priority]??5)-(priorityRank[b.priority]??5)||b.id-a.id,status:(a,b)=>(statusRank[a.status]??5)-(statusRank[b.status]??5)||b.id-a.id}[s]||((a,b)=>b.id-a.id);return list.slice().sort(by)}
function updateRows(){const body=document.getElementById('ticketrows');if(!body)return;const list=filtered();body.innerHTML=rows(list);body.querySelectorAll('tr').forEach((r,i)=>{r.style.animation=`rowIn .4s var(--out) both ${Math.min(i,8)*30}ms`});document.getElementById('resultsCount').textContent=ticketsCount(list.length);const chips=document.getElementById('statusChips');if(chips)chips.innerHTML=statusChips()}
function events(logs){return logs.length?`<div class="timeline">${logs.map(l=>`<div class="event"><p>${l.actor?`<strong>${esc(tr(l.actor))}</strong>: `:''}${esc(l.actor!==undefined?trEvent(l.message):l.text)}</p><small title="${esc(formatTime(l.at))}">${l.id?'<bdi dir="ltr">#'+l.id+'</bdi> · ':''}${esc(ago(l.at))}</small></div>`).join('')}</div>`:`<p class="muted" style="font-size:12.5px">${tr('لا توجد إجراءات مسجلة بعد.')}</p>`}
function details(){const t=ticket(),done=t.tasks.filter(x=>x.done).length,pending=t.handover?.state==='pending',me=currentUser();
  const action=(isTech()&&t.status!=='مكتمل'&&(t.ownerId===me.id||pending&&t.handover?.toId===me.id)?`<button class="btn" onclick="go('${pending?'review':'handover'}')">${icon('swap')}${tr(pending?'مراجعة طلب التسليم':'تسليم البلاغ لفني آخر')}</button>`:'')+`<button class="iconbtn" onclick="copyTicketLink()" aria-label="${esc(tr('نسخ رابط البلاغ'))}" title="${esc(tr('نسخ رابط البلاغ'))}">${icon('copy')}</button><button class="iconbtn" onclick="window.print()" aria-label="${esc(tr('طباعة البلاغ'))}" title="${esc(tr('طباعة البلاغ'))}">${icon('print')}</button>`;
  return `<button class="linkbtn back" onclick="go('tickets')">${icon('back')}${tr('العودة للبلاغات')}</button>`+heading(esc(t.title),`${esc(tr(t.category))} · ${esc(t.place)}${t.createdAt?` · <span title="${esc(formatTime(t.createdAt))}">${esc(tr('أُنشئ {when}',{when:ago(t.createdAt)}))}</span>`:''}`,action,`${tr('بلاغ')} ${ticketRef(t.id)}`)+`<div class="notice ${pending?'amber':''}">${icon(pending?'clock':'user')}<span>${tr('المسؤول الحالي:')} <strong>${esc(tr(t.owner))}</strong>${pending?' · '+esc(tr('طلب التسليم بانتظار قبول {name}',{name:t.handover.to})):' · '+tr('أي إجراء جديد سيُضاف إلى سجل البلاغ.')}</span></div><div class="detailgrid"><div><section class="panel"><div class="panelhead">${panelTitle('file',tr('وصف المشكلة'))}<div class="badges">${badge(t.priority)}${badge(t.status)}</div></div><div class="panelbody"><p class="description">${esc(t.description)}</p>${priorityPanel(t)}${isTech()&&t.owner==='بانتظار الإسناد'?`<button class="btn sectionspace" onclick="assignMe()">${icon('wrench')}${tr('استلام معالجة البلاغ')}</button>`:''}</div></section><section class="panel"><div class="panelhead">${panelTitle('check',tr('الإجراءات والخطوات المتبقية'))}${progressRing(done,t.tasks.length)}</div><div class="panelbody"><div style="display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-bottom:8px"><span>${tr('التقدم')}</span><span>${tr('{done} من {total} مكتملة',{done,total:t.tasks.length})}</span></div><div class="progress" style="margin-bottom:16px"><span style="width:${t.tasks.length?done/t.tasks.length*100:0}%"></span></div>${tasklist(t)}${isTech()&&t.ownerId===me.id?`<div class="actions"><button class="btn secondary sm" onclick="openTask()">${icon('plus')}${tr('إضافة خطوة')}</button><button class="btn sm" onclick="closeTicket()" ${t.status==='مكتمل'?'disabled':''}>${icon('check')}${tr('إغلاق البلاغ')}</button></div><small style="display:block;margin-top:10px">${tr('يتطلب الإغلاق اكتمال جميع الخطوات وعدم وجود طلب تسليم معلّق.')}</small>`:''}</div></section><section class="panel"><div class="panelhead">${panelTitle('clock',tr('سجل الإجراءات'))}<button class="btn secondary sm" onclick="openNote()">${icon('note')}${tr('إضافة ملاحظة')}</button></div><div class="panelbody">${events(t.logs)}</div></section></div><div>${contactPanel(t)}<section class="panel"><div class="panelhead">${panelTitle('info',tr('بيانات البلاغ'))}</div><div class="panelbody"><div class="info"><span class="muted">${icon('user')}${tr('المسؤول')}</span>${person(t.owner)}</div><div class="info"><span class="muted">${icon('tag')}${tr('التصنيف')}</span><span>${esc(tr(t.category))}</span></div><div class="info"><span class="muted">${icon('flag')}${tr('الأولوية')}</span>${badge(t.priority)}</div><div class="info"><span class="muted">${icon('pin')}${tr('الموقع')}</span><span>${esc(t.place)}</span></div><div class="info"><span class="muted">${icon('ticket')}${tr('الحالة')}</span>${badge(t.status)}</div>${t.createdAt?`<div class="info"><span class="muted">${icon('clock')}${tr('تاريخ الإنشاء')}</span><span>${esc(formatTime(t.createdAt))}</span></div>`:''}</div></section><section class="panel"><div class="panelhead">${panelTitle('spark',tr('ملخص المتابعة'))}<span class="badge violet"><i class="bd"></i>${tr('ملخص')}</span></div><div class="panelbody"><div class="summary">${esc(summary(t))}</div><small style="display:block;margin-top:12px">${tr('ملخص من بيانات البلاغ. راجع التفاصيل والإجراءات قبل متابعة العمل.')}</small></div></section></div></div>`}
function transfer(from,to,big=false,toId='toName'){return `<div class="transfer ${big?'big':''}"><div class="who"><span class="miniavatar">${esc(initials(from))}</span><span>${esc(from)}<small>${tr('المسلّم')}</small></span></div><span class="flow" aria-hidden="true"></span><div class="who"><span class="miniavatar">${esc(initials(to))||'?'}</span><span><span id="${toId}">${esc(to)}</span><small>${tr('المستلم')}</small></span></div></div>`}
const handoverReasons={shift_end:'انتهاء الوردية',specialization:'الحاجة إلى تخصص آخر',workload:'إعادة توزيع المهام'};
function handover(){const t=ticket(),d=db.drafts[t.id]||{};if(t.handover?.state==='pending')return review();if(t.ownerId!==currentUser()?.id)return details();if(t.status==='مكتمل')return details();const others=accounts.filter(a=>a.role==='tech'&&a.id!==currentUser().id);const firstTo=others.find(a=>a.id===d.toId)||others[0];return `<button class="linkbtn back" onclick="go('details')">${icon('back')}${tr('العودة لتفاصيل البلاغ')}</button>`+heading(tr('تسليم المهمة'),tr('وثّق نقطة التوقف والخطوة التالية للبلاغ {ref}.',{ref:ticketRef(t.id)}))+`<div class="notice">${icon('user')}<span>${tr('يبقى {name} مسؤولًا عن البلاغ حتى يقبل الفني المستلم طلب التسليم.',{name:`<strong>${esc(t.owner)}</strong>`})}</span></div>${!others.length?`<div class="notice amber">${icon('warn')}<span>${tr('لا يوجد فني آخر مسجّل بعد. أنشئ حساب فني آخر من بوابة الفنيين لتجربة التسليم.')}</span></div>`:''}<form id="handoverForm" onsubmit="sendHandover(event)"><div class="detailgrid"><section class="panel"><div class="panelhead">${panelTitle('swap',tr('تفاصيل التسليم'))}<span class="refchip">${ticketRef(t.id)}</span></div><div class="panelbody"><div class="formtwo"><div class="fieldgroup"><label class="fieldlabel" for="receiver">${tr('الفني المستلم')}</label><select id="receiver" required onchange="const n=document.getElementById('toName');if(n)n.textContent=this.selectedOptions[0].textContent">${others.map(a=>`<option value="${esc(a.id)}" ${d.toId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')||`<option value="">${tr('لا يوجد فني آخر مسجل')}</option>`}</select></div><div class="fieldgroup"><label class="fieldlabel" for="reason">${tr('سبب التسليم')}</label><select id="reason">${Object.entries(handoverReasons).map(([code,n])=>`<option value="${code}" ${d.reasonCode===code?'selected':''}>${tr(n)}</option>`).join('')}</select></div></div><div class="fieldgroup"><label class="fieldlabel" for="summary">${tr('ملخص التسليم — قابل للتعديل')}</label><textarea id="summary" required maxlength="4000">${esc(d.summary||summary(t))}</textarea><small>${tr('راجعه وأضف التفاصيل المهمة قبل الإرسال.')}</small></div><div class="fieldgroup"><label class="fieldlabel" for="notes">${tr('ملاحظات للفني المستلم')}</label><textarea id="notes" maxlength="2500" placeholder="${esc(tr('نقطة التوقف، أي عوائق، وما الذي يجب البدء به…'))}">${esc(d.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn secondary" onclick="saveDraft()">${icon('file')}${tr('حفظ كمسودة')}</button><button type="submit" class="btn">${icon('swap')}${tr('إرسال طلب التسليم')}</button></div></div></section><div><section class="panel"><div class="panelhead">${panelTitle('ticket',tr('ما الذي سينتقل؟'))}</div><div class="panelbody">${transfer(t.owner,firstTo?.name||'—')}<h3>${esc(t.title)}</h3><p class="subtitle">${esc(t.place)}</p><div class="sectionspace">${tasklist(t,false)}</div></div></section></div></div></form>`}
function draftValues(){return {to:document.getElementById('receiver').selectedOptions[0].textContent,toId:document.getElementById('receiver').value,reason:document.getElementById('reason').value,summary:document.getElementById('summary').value.trim(),notes:document.getElementById('notes').value.trim()}}
function handovers(){const pending=db.tickets.filter(t=>t.handover?.state==='pending'),past=db.tickets.filter(t=>t.handover&&t.handover.state!=='pending');return heading(tr('تسليم المهام'),tr('طلبات واضحة؛ وسجل واحد يحفظ تفاصيل انتقال العمل.'))+`<section class="panel"><div class="panelhead"><h2><span class="chip">${icon('swap')}</span>${tr('بانتظار الاستلام')} <span class="pillnum">${pending.length}</span></h2>${pending.length?`<span class="live" style="font-size:11.5px;color:var(--amber)"><span class="sig wait"></span>${tr('تنتظر القرار')}</span>`:''}</div><div class="panelbody">${pending.length?pending.map(t=>`<div class="queuecard"><div class="badges"><span class="refchip">${ticketRef(t.id)}</span>${badge('بانتظار الاستلام')}${badge(t.priority)}</div><h3 style="margin:10px 0 0">${esc(t.title)}</h3>${transfer(t.handover.from,t.handover.to,false,'to'+t.id)}<button class="btn sm" onclick="selected=${t.id};go('review')">${tr('مراجعة الطلب')} ${icon('arrow')}</button></div>`).join(''):`<div class="empty">${icon('inbox')}<p>${tr('لا توجد طلبات تسليم معلّقة.')}</p><p style="font-size:12px;margin:6px 0 16px">${tr('ابدأ من تفاصيل البلاغ الذي تريد تسليمه.')}</p><button class="btn secondary sm" onclick="go('tickets')">${tr('عرض البلاغات')}</button></div>`}</div></section>${past.length?`<section class="panel"><div class="panelhead">${panelTitle('clock',tr('الطلبات السابقة'))}</div><div class="panelbody">${past.map(t=>`<div class="queuecard"><div class="badges">${badge(t.handover.state==='accepted'?'مقبول':'مرفوض')}<span class="refchip">${ticketRef(t.id)}</span></div><p style="font-weight:600">${esc(t.title)}</p><small>${esc(t.handover.from)} ${lang==='en'?'→':'←'} ${esc(t.handover.to)}</small>${t.handover.declineReason?`<p class="muted" style="font-size:12px">${tr('سبب الرفض:')} ${esc(t.handover.declineReason)}</p>`:''}<br><button class="linkbtn" style="margin-top:8px" onclick="openTicket(${t.id})">${tr('عرض سجل البلاغ')} ${icon('arrow')}</button></div>`).join('')}</div></section>`:''}`}
function review(){const t=ticket(),h=t.handover;if(!h||h.state!=='pending')return details();const mine=h.toId===currentUser().id;return heading(tr('مراجعة طلب الاستلام'),`${tr('منظور الفني المستلم:')} ${esc(h.to)} · ${tr('بلاغ')} ${ticketRef(t.id)}`)+`<div class="notice amber">${icon('clock')}<span>${mine?tr('أنت الفني المستلم لهذا الطلب.'):esc(tr('الطلب موجّه إلى {name}. سجّل الدخول بحسابه لاتخاذ القرار.',{name:h.to}))} ${esc(tr('المسؤول الحالي هو {name}، ولا يتغيّر إلا بعد قبول الطلب.',{name:t.owner}))}</span></div><div class="detailgrid"><section class="panel"><div class="panelhead"><h2>${esc(t.title)}</h2>${badge(t.priority)}</div><div class="panelbody">${transfer(h.from,h.to,true,'rv')}<div class="formtwo sectionspace"><div class="fieldgroup"><small>${tr('الفني المسلّم')}</small><h3>${esc(h.from)}</h3></div><div class="fieldgroup"><small>${tr('سبب التسليم')}</small><h3>${esc(tr(h.reason))}</h3></div></div><h3 style="margin-bottom:10px">${tr('ملخص التسليم')}</h3><div class="summary">${esc(h.summary)}</div><h3 class="sectionspace">${tr('ملاحظات المسلّم')}</h3><p class="description" style="margin-top:6px">${esc(h.notes||tr('لا توجد ملاحظات إضافية.'))}</p>${mine?`<div class="reviewchecks sectionspace"><label><input id="reviewed" type="checkbox" onchange="document.getElementById('accept').disabled=!this.checked">${tr('راجعت التفاصيل والخطوات المتبقية وأستطيع متابعة المهمة.')}</label></div><div class="actions"><button class="btn danger" onclick="openDecline()">${tr('رفض الاستلام')}</button><button class="btn" id="accept" disabled onclick="accept()">${icon('check')}${tr('قبول الاستلام')}</button></div>`:''}</div></section><section class="panel"><div class="panelhead">${panelTitle('check',tr('الإجراءات المسجلة'))}</div><div class="panelbody">${tasklist(t,false)}<small style="display:block;margin-top:15px">${tr('وقت إرسال الطلب:')} ${esc(formatTime(h.at))}</small></div></section></div>`}
function success(){const t=ticket();const colors=['#237A68','#D6AA56','#2FD38A','#83C4AE','#FF6B76'];const bursts=Array.from({length:18},(_,i)=>{const a=i/18*Math.PI*2,r=90+(i%3)*40;return `<i class="burst" style="background:${colors[i%5]};--x:${Math.cos(a)*r|0}px;--y:${Math.sin(a)*r|0}px"></i>`}).join('');return heading(tr('اكتمل تسليم المهمة'),`${tr('بلاغ')} ${ticketRef(t.id)}`)+`<div class="successbox">${bursts}<div class="checkmark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12l4 4L19 6"/></svg></div><h2>${tr('تم قبول الاستلام وتحديث المسؤول')}</h2><p class="description">${tr('المسؤول الحالي عن البلاغ:')} <strong>${esc(tr(t.owner))}</strong></p><button class="btn sectionspace" onclick="go('details')">${tr('متابعة تفاصيل البلاغ')} ${icon('arrow')}</button></div><section class="panel"><div class="panelhead">${panelTitle('clock',tr('سجل انتقال العمل'))}</div><div class="panelbody">${events(t.logs)}</div></section>`}
function tasks(){const ts=db.tickets.filter(t=>t.ownerId===currentUser()?.id&&t.status!=='مكتمل');return heading(tr('مهامي'),tr('خطوات البلاغات المسندة إليك، مع تحديث مباشر للإنجاز.'))+(ts.length?ts.map(t=>{const d=t.tasks.filter(x=>x.done).length;return `<section class="panel"><div class="panelhead"><div style="display:flex;align-items:center;gap:14px;min-width:0">${progressRing(d,t.tasks.length)}<div style="min-width:0"><h2>${esc(t.title)}</h2><div class="badges" style="margin-top:4px">${badge(t.priority)}${badge(t.status)}</div></div></div><button class="linkbtn" onclick="openTicket(${t.id})">${ticketRef(t.id)} ${icon('arrow')}</button></div><div class="panelbody">${tasklist(t)}</div></section>`}).join(''):`<div class="panel empty">${icon('check')}<p>${tr('لا توجد مهام نشطة مسندة إليك.')}</p></div>`)}
function activity(){const logs=visibleTickets().flatMap(t=>t.logs.map(l=>({...l,id:formatId(t.id)}))).sort((a,b)=>(b.at||0)-(a.at||0));return heading(tr('سجل النشاط'),tr('الإجراءات المسجلة على البلاغات المسموح لك بالاطلاع عليها.'))+`<section class="panel"><div class="panelhead">${panelTitle('clock',tr('سجل الإجراءات والتسليم'))}<span class="badge violet"><i class="bd"></i>${tr('سجل موحّد')}</span></div><div class="panelbody">${events(logs)}</div></section>`}
let notificationState={items:[],unread_count:0},notificationOwner=null,seenNotificationIds=null,notificationLoading=false;
function applyNotificationFeed(feed){const owner=currentSession?.user?.id;if(owner!==notificationOwner){notificationOwner=owner;seenNotificationIds=null}const items=Array.isArray(feed?.items)?feed.items:[];const fresh=seenNotificationIds?items.filter(n=>!seenNotificationIds.has(n.id)&&!n.read_at):[];notificationState={items,unread_count:Number(feed?.unread_count)||0};seenNotificationIds=new Set(items.map(n=>n.id));if(isTech()&&fresh.length)toast(fresh.length===1?tr(fresh[0].kind==='handover'?'وصلك طلب تسليم بلاغ ':'وصل بلاغ جديد ')+('#'+formatId(fresh[0].ticket_id)):tr('وصلت {n} إشعارات جديدة. افتح الجرس للاطلاع عليها.',{n:fresh.length}),'info')}
function renderNotificationBell(){const bell=document.getElementById('bell');const count=isTech()?notificationState.unread_count:0;bell.hidden=!isTech();bell.setAttribute('aria-label',tr('الإشعارات')+(count?tr('، {n} غير مقروءة',{n:count}):''));bell.innerHTML=icon('bell')+(count?`<span class="notification-count">${count>99?'99+':count}</span>`:'')}
function notifications(){return heading(tr('الإشعارات'),tr('بلاغات جديدة وطلبات تسليم موجّهة لك. يتم التحقق من الجديد كل ١٥ ثانية أثناء فتح مرصاد.'),`<button class="btn secondary sm" onclick="markAllNotificationsRead()" ${notificationState.unread_count?'':'disabled'}>${tr('تحديد الكل كمقروء')}</button>`)+`<section class="panel"><div class="panelhead">${panelTitle('bell',tr('مركز الإشعارات'))}<span class="badge amber">${tr('{n} غير مقروء',{n:notificationState.unread_count})}</span></div><div class="panelbody notification-list">${notificationState.items.length?notificationState.items.map(n=>`<button class="notification-item ${n.read_at?'':'unread'}" onclick="openNotification('${esc(n.id)}')"><span class="chip">${icon(n.kind==='handover'?'swap':'ticket')}</span><span class="notification-text"><strong>${tr(n.kind==='handover'?'طلب تسليم لك':'بلاغ جديد')} · ${ticketRef(n.ticket_id)}</strong><span>${esc(n.title)}</span><small>${esc(formatTime(n.created_at))}${n.read_at?' · '+tr('تمت القراءة'):' · '+tr('جديد')}</small></span>${icon('arrow')}</button>`).join(''):`<p class="description">${tr('لا توجد إشعارات حتى الآن. ستظهر هنا البلاغات الجديدة وطلبات التسليم التي تصلك.')}</p>`}</div></section>`}
async function refreshNotifications(){if(notificationLoading||!isTech())return;notificationLoading=true;const owner=currentSession?.user?.id;try{const feed=await api('notifications');if(owner!==currentSession?.user?.id)return;applyNotificationFeed(feed);renderNotificationBell();if(page==='notifications')document.getElementById('app').innerHTML=workspaceNotice()+notifications()}catch{/* Keep the last known feed; normal workspace refresh reports connection errors. */}finally{notificationLoading=false}}
async function openNotification(id){const n=notificationState.items.find(n=>n.id===id);if(!n||!isTech())return;try{await api('notifications/read',{id:n.id});await refreshWorkspace(false);const t=db.tickets.find(t=>t.id===Number(n.ticket_id));if(!t)return toast(tr('هذا البلاغ غير موجود ضمن النتائج الحالية. ابحث عنه برقم البلاغ.'),'info');selected=t.id;go(n.kind==='handover'&&t.handover?.state==='pending'&&t.handover.toId===currentUser().id?'review':'details')}catch(e){toast(e.message,'error')}}
async function markAllNotificationsRead(){await mutation('notifications/read',{id:null},tr('تم تحديد الإشعارات كمقروءة.'))}
function skeleton(){return `<div class="sk skel-head"></div><div class="skel-stats"><div class="sk"></div><div class="sk"></div><div class="sk"></div><div class="sk"></div></div><div class="loading-line"><span class="sig ai"></span>${tr('جارٍ التحقق من الاتصال بخدمات الحسابات والبلاغات…')}</div><div class="sk skel-panel"></div>`}

// ---------- أدوات إضافية: تصدير، نسخ، اختصارات ----------
function exportCSV(){if(!isTech())return;const list=filtered();if(!list.length)return toast(tr('لا توجد بلاغات للتصدير.'),'info');const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const head=['رقم البلاغ','العنوان','التصنيف','الموقع','الأولوية','الحالة','المسؤول','الخطوات المكتملة','تاريخ الإنشاء'].map(tr);const body=list.map(t=>['#'+formatId(t.id),t.title,tr(t.category),t.place,tr(t.priority),tr(t.status),tr(t.owner),`${t.tasks.filter(x=>x.done).length}/${t.tasks.length}`,t.createdAt?formatTime(t.createdAt):'']);const csv='﻿'+[head,...body].map(r=>r.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`mirsad-tickets-${new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh'}).format(new Date())}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(tr('تم تصدير {n} بلاغ إلى ملف CSV.',{n:list.length}))}
async function copyTicketLink(){const url=location.origin+location.pathname+`#/details/${selected}`;try{await navigator.clipboard.writeText(url);toast(tr('تم نسخ رابط البلاغ.'))}catch{toast(url,'info')}}
function showShortcuts(){const items=[['/',tr('البحث في البلاغات')],['N',tr('إنشاء بلاغ جديد')],['G ثم D',tr('لوحة التحكم')],['G ثم T',tr('قائمة البلاغات')],['L',tr('تبديل اللغة')],['?',tr('عرض هذه القائمة')],['Esc',tr('إغلاق النافذة')]];modal(`<span class="chip" style="width:32px;height:32px">${icon('keyboard')}</span>${tr('اختصارات لوحة المفاتيح')}`,`<div class="shortcuts">${items.map(([k,l])=>`<div class="shortcut"><span>${esc(l)}</span><span>${String(k).split(' ').map(x=>x==='ثم'?`<small>${tr('ثم')}</small>`:`<kbd>${esc(x)}</kbd>`).join(' ')}</span></div>`).join('')}</div>`)}
function counter(el,id){const c=document.getElementById(id);if(c){const n=el.value.length,m=Number(el.maxLength)||0;c.textContent=`${n} / ${m}`;c.classList.toggle('near',m&&n>m*.9)}}

// ---------- Render ----------
function renderStatus(){const st=!serviceConfig?'wait':!serviceConfig.ready?'wait':workspaceError?'off':'on';const label=tr({on:'خدمات متصلة',off:'تعذّر الاتصال',wait:serviceConfig?'بانتظار الربط':'جارٍ الاتصال'}[st]);const key=lang+st+label;if(key===lastStatus)return;lastStatus=key;const pill=document.getElementById('serviceStatus');pill.className='status-pill '+st;pill.innerHTML=`<span class="sig ${st}"></span><span class="sp-text">${label}</span>`;pill.title=label;const sig=document.getElementById('sysSig');if(sig){sig.className='sig '+st;document.getElementById('sysText').textContent=tr(st==='on'?'جميع الخدمات تعمل':st==='off'?'تعذّر الاتصال بالخدمة':serviceConfig?'الخدمات بانتظار الربط':'جارٍ الاتصال بالخدمات');document.getElementById('sysNote').textContent=tr(st==='on'?'تحديث تلقائي كل 30 ثانية':'متابعة موحّدة من جميع أجهزتك')}}
function moveIndicator(){const ind=document.getElementById('navIndicator');if(!ind)return;const a=document.querySelector('.nav button.active');if(!a){ind.style.opacity='0';return}ind.style.opacity='1';ind.style.transform=`translateY(${a.offsetTop}px)`;ind.style.height=a.offsetHeight+'px'}
function countUp(){if(reducedMotion())return;document.querySelectorAll('#app .statval[data-count]').forEach(el=>{const to=+el.dataset.count;if(!to)return;const start=performance.now(),dur=900;const step=n=>{const p=Math.min(1,(n-start)/dur),v=Math.round(to*(1-Math.pow(1-p,3)));el.textContent=String(v).padStart(2,'0');if(p<1)requestAnimationFrame(step)};el.textContent='00';requestAnimationFrame(step)})}
function render(){
  renderAccount();renderStatus();
  const pendingCount=db.tickets.filter(t=>t.handover?.state==='pending').length;
  for(const [key,[ic,txt]]of Object.entries(navs)){const e=document.querySelector(`[data-page="${key}"]`);e.hidden=!isTech()&&['handovers','tasks','activity'].includes(key);e.style.display=e.hidden?'none':'';e.innerHTML=icon(ic)+`<span>${tr(key==='tickets'&&!isTech()?'بلاغاتي':txt)}</span>`+(key==='handovers'?`<span class="count ${pendingCount?'hot':''} ${lastPending!==null&&pendingCount!==lastPending?'bump':''}">${pendingCount}</span>`:'');e.classList.toggle('active',key===page||(key==='tickets'&&page==='details')||(key==='handovers'&&['handover','review','success'].includes(page)));e.setAttribute('aria-current',e.classList.contains('active')?'page':'false')}
  setTimeout(()=>document.querySelectorAll('.count.bump').forEach(c=>c.classList.remove('bump')),350);
  const crumb=document.getElementById('breadcrumb'),ctext=tr(navs[page]?.[1]||({details:'تفاصيل البلاغ',handover:'تسليم المهمة',review:'مراجعة الاستلام',success:'تأكيد التسليم',notifications:'الإشعارات'})[page]);if(crumb.textContent!==ctext){crumb.textContent=ctext;crumb.style.animation='none';void crumb.offsetWidth;crumb.style.animation=''}
  renderNotificationBell();lastPending=pendingCount;
  const mb=document.getElementById('menubtn');if(!mb.innerHTML)mb.innerHTML=icon('menu');
  const app=document.getElementById('app');
  app.innerHTML=!serviceConfig?skeleton():workspaceNotice()+({dashboard,tickets,details,handover,handovers,review,success,tasks,activity,notifications})[page]()+adminPanel();
  const viewKey=[page,lang,serviceConfig?1:0,currentUser()?.id||'',['details','handover','review','success'].includes(page)?selected:''].join('|');
  if(viewKey!==lastViewKey){lastViewKey=viewKey;app.classList.remove('enter');void app.offsetWidth;app.classList.add('enter');clearTimeout(enterTimer);enterTimer=setTimeout(()=>app.classList.remove('enter'),1500);countUp()}
  moveIndicator();syncRoute();
}

// ---------- Modal ----------
function modal(title,body){const d=document.getElementById('modal'),c=document.getElementById('modalcontent');clearTimeout(closeTimer);const wasOpen=d.open&&!d.classList.contains('closing');if(!d.open)modalReturn=document.activeElement;d.classList.remove('closing');c.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="iconbtn" onclick="closeModal()" aria-label="${esc(tr('إغلاق'))}">${icon('close')}</button></div><div class="modalbody">${body}</div>`;if(wasOpen){c.classList.remove('swap');void c.offsetWidth;c.classList.add('swap')}else if(!d.open)d.showModal();const f=c.querySelector('.modalbody input:not([type=checkbox]),.modalbody textarea');if(f)setTimeout(()=>f.focus({preventScroll:true}),80)}
function closeModal(){const d=document.getElementById('modal');if(!d.open)return;const done=()=>{d.classList.remove('closing');d.close();modalReturn?.focus?.()};if(reducedMotion())return done();d.classList.add('closing');clearTimeout(closeTimer);closeTimer=setTimeout(done,240)}
function openDecline(){if(!isTech()||ticket().handover?.toId!==currentUser().id)return;modal(tr('رفض استلام المهمة'),`<p class="description" style="margin-bottom:18px">${esc(tr('وضّح السبب حتى يستطيع الفني المسلّم متابعة البلاغ. سيبقى البلاغ باسم {name}.',{name:ticket().owner}))}</p><form onsubmit="decline(event)"><label class="fieldlabel" for="declineReason">${tr('سبب الرفض')} <span style="color:var(--red)">*</span></label><textarea id="declineReason" maxlength="2000" placeholder="${esc(tr('اكتب سببًا واضحًا للرفض'))}" required></textarea><p class="error" id="declineError"></p><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">${tr('تراجع')}</button><button class="btn danger" type="submit">${tr('تأكيد الرفض')}</button></div></form>`)}
const impactChoices={scope:{single:'أنا فقط',team:'عدة أشخاص أو قسم',organization:'معظم المؤسسة',unknown:'ما أعرف'},disruption:{blocked:'العمل متوقف',degraded:'أقدر أشتغل لكن بصعوبة',nonblocking:'العمل مستمر طبيعي',unknown:'ما أعرف'},onset:{now:'خلال الساعة الأخيرة',today:'اليوم',older:'من أكثر من يوم',unknown:'ما أعرف'},risk:{security:'رسالة فدية أو دخول غريب أو اشتباه اختراق',data_loss:'ملفات اختفت أو بيانات تتلف أو تضيع',none:'ما لاحظت أي مؤشرات من هذي',unknown:'ما أعرف'},workaround:{available:'نعم، أقدر أكمل بطريقة مؤقتة',unavailable:'لا يوجد بديل متاح',unknown:'ما أعرف'}};
function impactQuestion(id,label,choices){const t=typeof tr==='function'?tr:s=>s;return `<div class="fieldgroup"><label class="fieldlabel" for="${id}">${label} *</label><select id="${id}" required><option value="" disabled selected>${t('اختر إجابة')}</option>${Object.entries(choices).map(([key,text])=>`<option value="${key}">${t(text)}</option>`).join('')}</select></div>`}
// ملاحظة: إجابات الأسئلة تُرسل للذكاء الاصطناعي بالعربية دائمًا (بغض النظر عن لغة الواجهة) لثبات معايير التصنيف.
function ticketDescription(description,scope,disruption,workaround,onset,risk){const answers={scope,disruption,workaround,onset,risk};if(Object.entries(answers).some(([key,value])=>!Object.hasOwn(impactChoices[key],value)))throw new Error(typeof tr==='function'?tr('أجب عن الأسئلة الخمسة قبل إرسال البلاغ.'):'أجب عن الأسئلة الخمسة قبل إرسال البلاغ.');return description+'\n\nإجابات الموظف عن أثر المشكلة:\nمن المتأثر؟ '+impactChoices.scope[scope]+'\nكيف أثرت على العمل؟ '+impactChoices.disruption[disruption]+'\nهل يوجد حل مؤقت؟ '+impactChoices.workaround[workaround]+'\nمتى بدأت المشكلة؟ '+impactChoices.onset[onset]+'\nهل لاحظت مؤشرات أمنية أو فقدان بيانات؟ '+impactChoices.risk[risk]}
function contactPanel(t){const c=t.contact;if(!c)return '';return `<section class="panel"><div class="panelhead">${panelTitle('pin',tr('الموقع وبيانات التواصل'))}</div><div class="panelbody">${[['المبنى',c.building],['القسم',c.department],['الدور',c.floor],['رقم المكتب',c.office]].map(([label,value])=>`<div class="info"><span class="muted">${tr(label)}</span><span>${esc(value)}</span></div>`).join('')}<div class="info"><span class="muted">${tr('رقم الجوال')}</span><a class="phonelink" href="tel:${esc(c.phone)}"><bdi dir="ltr">${esc(c.phone)}</bdi></a></div></div></section>`}

function baseOpenNew(){if(!currentUser()){afterAuth='new';return openAuth('login','user')}modal(`<span class="chip" style="width:32px;height:32px">${icon('plus')}</span>${tr(isTech()?'تسجيل بلاغ جديد':'إنشاء بلاغ جديد')}`,`<form onsubmit="createTicket(event)"><div class="fieldgroup"><label class="fieldlabel" for="newTitle">${tr('عنوان المشكلة')} *<span class="counter" id="newTitleCount">0 / 100</span></label><input id="newTitle" required maxlength="100" placeholder="${esc(tr('وصف مختصر وواضح'))}" oninput="counter(this,'newTitleCount')"></div><div class="formtwo"><div class="fieldgroup"><label class="fieldlabel" for="newCategory">${tr('التصنيف')}</label><select id="newCategory">${Object.entries(categoryNames).map(([k,v])=>`<option value="${k}">${tr(v)}</option>`).join('')}</select></div></div><fieldset class="impact-questions"><legend>${tr('الموقع وبيانات التواصل')}</legend><div class="formtwo">${[['newBuilding','المبنى','مثال: المبنى الرئيسي',60],['newDepartment','القسم','مثال: الموارد البشرية',60],['newFloor','الدور','مثال: الأرضي أو ٢',30],['newOffice','رقم المكتب','مثال: B-204، أو لا يوجد',30]].map(([id,label,hint,max])=>`<div class="fieldgroup"><label class="fieldlabel" for="${id}">${tr(label)} *</label><input id="${id}" required maxlength="${max}" placeholder="${esc(tr(hint))}"></div>`).join('')}</div><div class="fieldgroup"><label class="fieldlabel" for="newPhone">${tr('رقم الجوال')} *</label><input id="newPhone" type="tel" dir="ltr" inputmode="tel" required maxlength="20" placeholder="${esc(tr('05xxxxxxxx أو +9665xxxxxxxx'))}"><small>${tr('للتواصل عند الحاجة. يُحفظ مع بيانات البلاغ ولا يُرسل إلى خدمة الذكاء الاصطناعي.')}</small></div></fieldset><div class="fieldgroup"><label class="fieldlabel" for="newDescription">${tr('تفاصيل المشكلة')} *<span class="counter" id="newDescCount">0 / 1800</span></label><textarea id="newDescription" required maxlength="1800" placeholder="${esc(tr('وش المشكلة؟ ومتى بدأت؟ اذكر أي رسالة خطأ أو مخاوف على البيانات.'))}" oninput="counter(this,'newDescCount')"></textarea></div><fieldset class="impact-questions"><legend>${tr('٥ إجابات سريعة تساعدنا نحدد الأولوية')}</legend><p class="description">${tr('اختر الأقرب لحالتك، وإذا ما تعرف اختر «ما أعرف».')}</p>${impactQuestion('newScope',tr('مين متأثر بالمشكلة؟'),impactChoices.scope)}${impactQuestion('newDisruption',tr('كيف أثّرت المشكلة على العمل؟'),impactChoices.disruption)}${impactQuestion('newWorkaround',tr('هل فيه حل مؤقت تقدر تكمل به عملك؟'),impactChoices.workaround)}${impactQuestion('newOnset',tr('متى بدأت المشكلة؟'),impactChoices.onset)}${impactQuestion('newRisk',tr('هل لاحظت مؤشرات أمنية أو فقدان بيانات؟'),impactChoices.risk)}</fieldset><div class="prioritybox"><div class="pb-title" style="margin-bottom:6px"><span class="chip">${icon('spark')}</span>${tr('الأولوية تُحدّد تلقائيًا')}</div>${tr('يحلل الذكاء الاصطناعي وصف المشكلة وتأثيرها على العمل، وإذا تعذّر التصنيف يراجعها فني معتمد.')}<p class="priorityreason">${tr('يُرسل عنوان المشكلة ووصفها وإجاباتك الخمس لخدمة الذكاء الاصطناعي لتحديد الأولوية. لا تضف كلمات مرور أو مفاتيح وصول.')}</p></div><p class="error" id="newError"></p><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">${tr('إلغاء')}</button><button class="btn" type="submit">${icon('spark')}${tr(isTech()?'تسجيل البلاغ':'إنشاء البلاغ')}</button></div></form>`)}
function openNote(){modal(tr('إضافة ملاحظة'),`<form onsubmit="addNote(event)"><label for="note" class="fieldlabel">${tr('الملاحظة')}<span class="counter" id="noteCount">0 / 2000</span></label><textarea id="note" required maxlength="2000" placeholder="${esc(tr('اكتب ملاحظة تُضاف إلى سجل البلاغ'))}" oninput="counter(this,'noteCount')"></textarea><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">${tr('إلغاء')}</button><button class="btn" type="submit">${icon('check')}${tr('حفظ الملاحظة')}</button></div></form>`)}
function openTask(){if(!isTech())return;modal(tr('إضافة خطوة متابعة'),`<form onsubmit="addTask(event)"><label for="tasktext" class="fieldlabel">${tr('ما الخطوة المطلوبة؟')}</label><input id="tasktext" required maxlength="180" placeholder="${esc(tr('مثال: إعادة تشغيل المحوّل في الطابق الثاني'))}"><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">${tr('إلغاء')}</button><button class="btn" type="submit">${icon('plus')}${tr('إضافة الخطوة')}</button></div></form>`)}

// ==========================================================================
// Live adapter: Supabase owns authentication; every ticket mutation is authorized by Postgres RPCs.
// ==========================================================================
let afterAuth=null,authMode='login',authRole='user',accounts=[],liveProfile=null,currentSession=null,authClient=null,serviceConfig=null,loadVersion=0,busy=false,workspaceError='',activeTicketRequestId=null;
const categoryNames={hardware:'الأجهزة',networks:'الشبكات',software:'البرامج',accounts:'الحسابات'};
const statusNames={new:'جديد',in_progress:'قيد العمل',pending_handover:'بانتظار الاستلام',completed:'مكتمل'};
const priorityNames={high:'عالية',medium:'متوسطة',low:'منخفضة'};
function currentUser(){if(!currentSession||!liveProfile)return null;return {id:liveProfile.id,name:liveProfile.full_name,email:currentSession.user.email,role:['technician','admin'].includes(liveProfile.role)&& (liveProfile.role==='admin'||liveProfile.technician_status==='approved')?'tech':'user',department:liveProfile.department,employeeId:liveProfile.employee_id,specialty:liveProfile.specialty}}
function isTech(){return currentUser()?.role==='tech'}
function isAdmin(){return liveProfile?.role==='admin'}
function formatId(id){return String(id).padStart(2,'0')}
function ticketRef(id){return `<bdi dir="ltr">#${formatId(id)}</bdi>`}
function visibleTickets(){return db.tickets}
function canView(t){return !!t&&!!currentUser()&&(isTech()||t.requesterId===currentUser().id)}
function formatTime(s){if(s===undefined||s===null||s==='')return '';const d=new Date(s);if(Number.isNaN(d.getTime()))return '';return new Intl.DateTimeFormat(locale(),{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Riyadh'}).format(d)}
function workspaceNotice(){if(!serviceConfig)return '';if(!serviceConfig.ready)return `<section class="connection-banner"><h2><span class="sig wait"></span>${tr('مساحة مرصاد جاهزة للربط')}</h2><p>${tr('لم تُربط خدمة الحسابات وقاعدة البيانات بعد. التسجيل وإنشاء البلاغات سيُتاحان بعد اكتمال الربط؛ لا تُنشأ حسابات أو بلاغات محلية بديلة.')}</p><ul><li><span class="sig wait"></span>${tr('حسابات المستخدمين والفنيين: بانتظار ربط Supabase')}</li><li><span class="sig wait"></span>${tr('قاعدة البيانات والصلاحيات: بانتظار تفعيل المخطط')}</li><li><span class="sig ${serviceConfig.aiReady?'on':'wait'}"></span>${tr('تحليل الأولوية:')} ${tr(serviceConfig.aiReady?'جاهز بعد ربط البيانات':'بانتظار ربط خدمة Groq')}</li></ul></section>`;return `${workspaceError?`<div class="notice amber">${icon('warn')}<span>${esc(workspaceError)}</span><button class="linkbtn" onclick="refreshWorkspace()">${icon('refresh')}${tr('إعادة المحاولة')}</button></div>`:''}${liveProfile?.requested_role==='technician'&&liveProfile.technician_status==='pending'?`<div class="pending-message"><span class="sig wait"></span>${tr('تم استلام طلب التسجيل كفني. صلاحيات الفني بانتظار اعتماد مسؤول النظام. يمكنك متابعة بلاغاتك الشخصية أثناء الانتظار.')}</div>`:''}${liveProfile?.technician_status==='rejected'?`<div class="notice amber">${icon('info')}<span>${tr('لم يُعتمد طلب حساب الفني. راجع مسؤول النظام؛ حساب المستخدم ما زال متاحًا.')}</span></div>`:''}`}
function roleLabel(short){return tr(isAdmin()?'مسؤول النظام':isTech()?(short?'فني معتمد':'فني دعم معتمد'):short?'حساب مستخدم':'مستخدم')}
function renderAccount(){const u=currentUser();document.getElementById('followLabel').hidden=!isTech();const html=u?`<button class="accountbtn" onclick="openAccount()" aria-label="${esc(tr('حساب {name}',{name:u.name}))}"><span class="avatar">${esc(initials(u.name))}</span><span class="profiletext">${esc(u.name)}<br><small>${roleLabel(true)}</small></span></button>`:`<div class="signin"><button class="btn secondary sm" onclick="openAuth('login','user')">${tr('تسجيل الدخول')}</button><button class="btn sm" onclick="openAuth('signup','user')">${tr('إنشاء حساب')}</button></div>`;const aa=document.getElementById('accountActions');if(aa.dataset.html!==html){aa.innerHTML=html;aa.dataset.html=html}const side=u?`<button class="accountbtn" onclick="openAccount()"><span class="avatar">${esc(initials(u.name))}</span><span style="text-align:start;line-height:1.5">${esc(u.name)}<br><small>${roleLabel(false)}</small></span></button>`:`<button class="accountbtn" onclick="openAuth('login','technician')"><span class="avatar">${icon('wrench')}</span><span style="text-align:start;line-height:1.5">${tr('بوابة الفنيين')}<br><small>${tr('تسجيل الدخول / طلب الانضمام')}</small></span></button>`;const sa=document.getElementById('sideAccount');if(sa.dataset.html!==side){sa.innerHTML=side;sa.dataset.html=side}}
async function api(path,body){const session=await authClient?.auth.getSession();const token=session?.data.session?.access_token;if(!token)throw Error(tr('سجّل الدخول للمتابعة.'));const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Accept-Language':lang,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(lang==='en'?(errorsEN[data.error]||tr(data.message||'تعذّر الاتصال بالخدمة.')):(data.message||'تعذّر الاتصال بالخدمة.'));return data}
function mapState(data){liveProfile=data.profile;applyNotificationFeed(data.notifications);const staff=data.staff||[];accounts=staff.map(a=>({id:a.id,name:a.full_name,specialty:a.specialty,role:'tech'}));const name=id=>id===liveProfile?.id?liveProfile.full_name:staff.find(a=>a.id===id)?.full_name||'فني الدعم';db={nextId:null,tickets:(data.tickets||[]).map(t=>{const h=(data.handovers||[]).filter(h=>h.ticket_id===t.id).sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at))[0];return {id:Number(t.id),title:t.title,category:categoryNames[t.category],place:t.location,contact:t.contact_details,description:t.description,createdAt:Date.parse(t.created_at)||null,status:statusNames[t.status],priority:t.priority_state==='ready'?priorityNames[t.priority]:['needs_review','failed'].includes(t.priority_state)||(t.priority_state==='processing'&&Date.parse(t.ai_started_at)<Date.now()-60000)?'بانتظار مراجعة فني':t.priority_state==='processing'?'جارٍ التحليل':'بانتظار التصنيف',priorityState:t.priority_state,prioritySource:t.priority_source,reviewReason:t.priority_review_reason,questions:Array.isArray(t.clarifying_questions)?t.clarifying_questions.filter(x=>typeof x==='string'):[],aiStartedAt:t.ai_started_at,priorityReason:t.priority_reason||'تُحدّد الأولوية بواسطة خدمة الذكاء الاصطناعي بعد تحليل وصف المشكلة.',aiSummary:t.ai_summary,owner:t.owner_id?name(t.owner_id):'بانتظار الإسناد',ownerId:t.owner_id,requesterId:t.requester_id,tasks:(data.tasks||[]).filter(x=>x.ticket_id===t.id).sort((a,b)=>Date.parse(a.created_at)-Date.parse(b.created_at)).map(x=>({id:x.id,text:x.text,done:x.done})),logs:(data.events||[]).filter(l=>l.ticket_id===t.id).map(l=>({actor:l.actor_name,message:l.message,text:l.actor_name+': '+l.message,time:formatTime(l.created_at),at:Date.parse(l.created_at)})).sort((a,b)=>b.at-a.at),handover:h?{id:h.id,to:name(h.recipient_id),toId:h.recipient_id,from:name(h.sender_id),fromId:h.sender_id,state:h.state,summary:h.summary,notes:h.notes,reason:handoverReasons[h.reason]||handoverReasons.workload,reasonCode:h.reason,time:formatTime(h.created_at),at:Date.parse(h.created_at),declineReason:h.decline_reason}:null}}),drafts:{},approvals:data.approvals||[]};for(const d of data.drafts||[])db.drafts[d.ticket_id]={to:name(d.recipient_id),toId:d.recipient_id,reason:handoverReasons[d.reason],reasonCode:d.reason,summary:d.summary,notes:d.notes};serviceConfig.aiReady=data.aiReady}
async function refreshWorkspace(showError=true){const version=++loadVersion;if(!currentSession){liveProfile=null;notificationState={items:[],unread_count:0};notificationOwner=null;seenNotificationIds=null;db=seed();page='dashboard';finishRoute();render();return}try{const data=await api('state');if(version!==loadVersion)return;mapState(data);workspaceError='';if(['details','handover','review','success'].includes(page)&&!db.tickets.some(t=>t.id===selected))page='tickets';if(!routeApplied){finishRoute();if(initialRoute)return applyRoute(initialRoute)}render()}catch(e){if(version!==loadVersion)return;workspaceError=e.message;if(showError)toast(e.message,'error');finishRoute();render()}}
function finishRoute(){routeApplied=true}
function adminPanel(){if(!isAdmin()||page!=='dashboard')return '';const pending=db.approvals||[];return `<section class="panel"><div class="panelhead">${panelTitle('users',tr('طلبات اعتماد الفنيين'))}<span class="badge ${pending.length?'amber':'green'}"><i class="bd"></i>${pending.length}</span></div><div class="panelbody">${pending.length?pending.map(a=>`<div class="queuecard" style="display:flex;align-items:center;gap:14px;flex-wrap:wrap"><span class="avatar">${esc(initials(a.full_name))}</span><div style="flex:1;min-width:180px"><h3>${esc(a.full_name)}</h3><p style="margin:2px 0 0" class="muted">${esc(tr(a.specialty))} · ${tr('رقم وظيفي:')} ${esc(a.employee_id)}</p></div><div class="actions" style="border:0;margin:0;padding:0"><button class="btn danger sm" onclick="reviewTechnician('${esc(a.id)}',false)">${tr('رفض الطلب')}</button><button class="btn sm" onclick="reviewTechnician('${esc(a.id)}',true)">${icon('check')}${tr('اعتماد الفني')}</button></div></div>`).join(''):`<p class="muted" style="font-size:12.5px">${tr('لا توجد طلبات اعتماد معلّقة.')}</p>`}</div></section>`}
async function mutation(path,payload,success,done){if(busy)return;busy=true;const button=document.activeElement;const oldDisabled=button?.disabled;if(button?.tagName==='BUTTON'){button.disabled=true;button.setAttribute('aria-busy','true')}try{const data=await api(path,payload);if(done)done(data);await refreshWorkspace(false);if(success)toast(typeof success==='function'?success(data):success);return data}catch(e){toast(e.message,'error');return null}finally{busy=false;if(button?.isConnected){button.disabled=oldDisabled;button.removeAttribute('aria-busy')}}}
function action(id,payload,success,done){return mutation(`tickets/${id}/action`,payload,success,done)}
function openNew(){if(!currentUser()){afterAuth='new';return openAuth('login','user')}activeTicketRequestId=crypto.randomUUID();baseOpenNew()}
async function createTicket(e){e.preventDefault();const val=id=>document.getElementById(id).value.trim();try{const contact={building:val('newBuilding'),department:val('newDepartment'),floor:val('newFloor'),office:val('newOffice'),phone:val('newPhone').replace(/[٠-٩۰-۹]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.includes(c)?'٠١٢٣٤٥٦٧٨٩'.indexOf(c):'۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[\s()-]/g,'')};if(Object.values(contact).some(v=>!v))throw Error(tr('أكمل بيانات الموقع ورقم الجوال.'));if(!/^(?:05[0-9]{8}|\+9665[0-9]{8}|009665[0-9]{8}|\+[1-9][0-9]{7,14})$/.test(contact.phone))throw Error(tr('اكتب رقم جوال صحيحًا مثل 05xxxxxxxx أو بصيغة دولية تبدأ بـ +.'));if(!val('newTitle')||!val('newDescription'))return;const rawCategory=val('newCategory'),category=Object.hasOwn(categoryNames,rawCategory)?rawCategory:Object.keys(categoryNames).find(k=>categoryNames[k]===rawCategory)||'hardware';const body={title:val('newTitle'),location:[contact.building,contact.department].join(' · ').slice(0,90),contact,description:ticketDescription(val('newDescription'),val('newScope'),val('newDisruption'),val('newWorkaround'),val('newOnset'),val('newRisk')),category,requestId:activeTicketRequestId};await mutation('tickets',body,d=>d.classification?.warning?tr(d.classification.warning):tr('تم إنشاء البلاغ {ref}',{ref:'#'+formatId(d.id)}),d=>{selected=Number(d.id);closeModal();page='details';activeTicketRequestId=null;pushRoute()})}catch(error){document.getElementById('newError').textContent=error.message}}

function setTask(id,i,value){const t=db.tickets.find(t=>t.id===id);if(!t||t.ownerId!==currentUser()?.id){render();return toast(tr('تحديث الخطوات متاح للفني المسؤول.'),'info')}action(id,{action:'set_task',task_id:t.tasks[i].id,done:value},tr('تم تحديث الخطوة.')).then(d=>{if(!d)render()})}
function assignMe(){action(ticket().id,{action:'claim'},tr('تم إسناد البلاغ إليك.'))}
function closeTicket(){action(ticket().id,{action:'close'},tr('تم إغلاق البلاغ.'))}
function addTask(e){e.preventDefault();const value=document.getElementById('tasktext').value.trim();if(value)action(ticket().id,{action:'add_task',text:value},tr('أُضيفت الخطوة.'),closeModal)}
function addNote(e){e.preventDefault();const value=document.getElementById('note').value.trim();if(value)action(ticket().id,{action:'note',text:value},tr('تم حفظ الملاحظة.'),closeModal)}
function summary(t){const done=t.tasks.filter(x=>x.done).map(x=>tr(x.text)),todo=t.tasks.filter(x=>!x.done).map(x=>tr(x.text));const sep=lang==='en'?', ':'، ';return (t.aiSummary||t.description)+'\n\n'+tr('تم إنجازه: ')+(done.join(sep)||tr('لم تسجل خطوات مكتملة بعد'))+'\n'+tr('الخطوات المتبقية: ')+(todo.join(sep)||tr('لا توجد خطوات متبقية'))}
function handoverPayload(kind){const d=draftValues();return {action:kind,recipient_id:d.toId||null,reason:Object.hasOwn(handoverReasons,d.reason)?d.reason:'workload',summary:d.summary,notes:d.notes}}
function saveDraft(){action(ticket().id,handoverPayload('draft'),tr('تم حفظ المسودة في حسابك.'))}
function sendHandover(e){e.preventDefault();const payload=handoverPayload('send');if(!payload.recipient_id)return toast(tr('اختر فنيًا معتمدًا لاستقبال المهمة.'),'error');action(ticket().id,payload,tr('أُرسل طلب التسليم. المسؤولية لم تنتقل بعد.'),()=>{page='review'})}
function accept(){if(!document.getElementById('reviewed')?.checked)return;action(ticket().id,{action:'accept',handover_id:ticket().handover.id,acknowledged:true},tr('تم قبول الاستلام وتحديث المسؤول.'),()=>{page='success'})}
function decline(e){e.preventDefault();const reason=document.getElementById('declineReason').value.trim();if(!reason)return;action(ticket().id,{action:'decline',handover_id:ticket().handover.id,reason},tr('تم توثيق الرفض. المسؤول السابق لم يتغيّر.'),()=>{closeModal();page='details'})}
function retryClassification(id){mutation(`tickets/${id}/classify`,{},d=>d.warning?tr(d.warning):tr('تم تحديث تصنيف الأولوية.'))}
function reviewTechnician(id,approve){mutation('technicians/review',{profileId:id,approve},tr(approve?'تم اعتماد الفني.':'تم رفض طلب الفني.'))}
function openAuth(mode='login',role='user'){authMode=mode;authRole=role==='tech'?'technician':role;showAuth()}
function setAuthMode(mode){authMode=mode;showAuth()}
function setAuthRole(role){authRole=role;showAuth()}
function pwField(id,auto){return `<div class="pwfield"><input id="${id}" type="password" required minlength="8" autocomplete="${auto}"><button type="button" aria-label="${esc(tr('إظهار كلمة المرور'))}" onclick="const i=document.getElementById('${id}');const s=i.type==='password';i.type=s?'text':'password';this.innerHTML=s?icon('eyeoff'):icon('eyeic')">${icon('eyeic')}</button></div>`}
const specialties=['الدعم الفني العام','الشبكات','الأجهزة','الأنظمة والحسابات'];
function showAuth(){const tech=authRole==='technician',signup=authMode==='signup';modal(tr(signup?'إنشاء حساب':'تسجيل الدخول'),`<div class="authhero"><div class="eyewrap">${eye()}</div><div><strong>${tr(signup?'انضم إلى مساحة مرصاد':'أهلًا بعودتك')}</strong><p>${tr(tech?'بوابة فنيي الدعم: معالجة البلاغات وتسليم المهام.':'أرسل بلاغك وتابع تقدّم الحل لحظة بلحظة.')}</p></div></div>${!serviceConfig?.ready?`<p class="notice amber">${icon('info')}<span>${tr('خدمة الحسابات بانتظار الربط. يمكنك استعراض الحقول، ولن يُنشأ حساب محلي.')}</span></p>`:''}<div class="authchoice"><button class="rolebtn ${!tech?'active':''}" type="button" onclick="setAuthRole('user')"><span class="chip">${icon('user')}</span><span><strong>${tr('مستخدم')}</strong><small>${tr('إرسال البلاغات ومتابعتها')}</small></span><span class="tick">${icon('check')}</span></button><button class="rolebtn ${tech?'active':''}" type="button" onclick="setAuthRole('technician')"><span class="chip">${icon('wrench')}</span><span><strong>${tr('فني دعم تقني')}</strong><small>${tr('معالجة البلاغات وتسليم المهام')}</small></span><span class="tick">${icon('check')}</span></button></div><div class="authmode ${signup?'signup':''}"><button class="${!signup?'active':''}" type="button" onclick="setAuthMode('login')">${tr('تسجيل الدخول')}</button><button class="${signup?'active':''}" type="button" onclick="setAuthMode('signup')">${tr('إنشاء حساب')}</button></div><form id="authform" onsubmit="submitAuth(event)">${signup?`<div class="fieldgroup"><label class="fieldlabel" for="authName">${tr('الاسم الكامل')} *</label><input id="authName" required maxlength="60" autocomplete="name"></div>`:''}<div class="fieldgroup"><label class="fieldlabel" for="authEmail">${tr(tech?'البريد الوظيفي':'البريد الإلكتروني')} *</label><input id="authEmail" type="email" required dir="ltr" autocomplete="email" placeholder="name@example.com"></div>${signup&&tech?`<div class="formtwo"><div class="fieldgroup"><label class="fieldlabel" for="employeeId">${tr('الرقم الوظيفي')} *</label><input id="employeeId" required maxlength="35"></div><div class="fieldgroup"><label class="fieldlabel" for="specialty">${tr('التخصص')}</label><select id="specialty">${specialties.map(s=>`<option value="${s}">${tr(s)}</option>`).join('')}</select></div></div><p class="authnote">${icon('shield')}${tr('يُراجع مسؤول النظام طلب حساب الفني قبل منح صلاحيات المعالجة.')}</p>`:signup?`<div class="fieldgroup"><label class="fieldlabel" for="department">${tr('القسم أو الجهة')} *</label><input id="department" required maxlength="90"></div>`:''}<div class="fieldgroup"><label class="fieldlabel" for="authPassword">${tr('كلمة المرور')} *</label>${pwField('authPassword',signup?'new-password':'current-password')}</div>${signup?`<div class="fieldgroup"><label class="fieldlabel" for="authConfirm">${tr('تأكيد كلمة المرور')} *</label>${pwField('authConfirm','new-password')}</div>`:`<button type="button" class="linkbtn" onclick="openRecovery()">${tr('نسيت كلمة المرور؟')}</button>`}<p class="error" id="authError" role="alert"></p><button class="btn block" id="authSubmit" type="submit" ${!serviceConfig?.ready?'disabled':''}>${tr(signup?'إنشاء الحساب':'تسجيل الدخول')} ${tr(tech?'كفني':'كمستخدم')}</button></form>`)}
async function submitAuth(e){e.preventDefault();if(!authClient)return;const button=document.getElementById('authSubmit'),error=document.getElementById('authError');button.disabled=true;button.setAttribute('aria-busy','true');error.textContent='';try{const email=document.getElementById('authEmail').value.trim(),password=document.getElementById('authPassword').value;let result;if(authMode==='signup'){const name=document.getElementById('authName').value.trim();if(!name)throw Error(tr('اكتب الاسم الكامل.'));if(password!==document.getElementById('authConfirm').value)throw Error(tr('كلمتا المرور غير متطابقتين.'));const extra=authRole==='technician'?{employee_id:document.getElementById('employeeId').value.trim(),specialty:document.getElementById('specialty').value}:{department:document.getElementById('department').value.trim()};result=await authClient.auth.signUp({email,password,options:{emailRedirectTo:location.origin+'/',data:{full_name:name,requested_role:authRole,...extra}}});if(result.error)throw Error(authMessage(result.error));if(!result.data.session){closeModal();toast(tr('راجع بريدك لتأكيد الحساب، ثم سجّل الدخول.'),'info');return}}else{result=await authClient.auth.signInWithPassword({email,password});if(result.error)throw Error(authMessage(result.error))}currentSession=result.data.session;closeModal();page='dashboard';await refreshWorkspace();if(authRole==='technician'&&!isTech())toast(tr('حسابك لا يملك صلاحية الفني بعد. راجع حالة طلب الاعتماد.'),'info');else toast(tr('أهلًا {name}',{name:currentUser()?.name||''}));if(afterAuth==='new'){afterAuth=null;openNew()}}catch(e){error.textContent='';void error.offsetWidth;error.textContent=e.message}finally{if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy')}}}
function authMessage(e){if(e.code==='email_not_confirmed')return tr('أكّد بريدك الإلكتروني أولًا.');if(e.code==='user_already_exists')return tr('الحساب موجود؛ جرّب تسجيل الدخول.');if(e.code==='over_email_send_rate_limit'||e.status===429)return tr('وصلت إلى حد المحاولات. انتظر قليلًا.');if(e.code==='weak_password')return tr('اختر كلمة مرور أقوى.');if(e.code==='invalid_credentials')return tr('البريد أو كلمة المرور غير صحيحة.');return tr('تعذّر إكمال العملية. تحقق من البيانات أو تأكيد البريد وحاول مرة أخرى.')}
function openAccount(){const u=currentUser();if(!u)return openAuth();modal(tr('حسابي'),`<div class="accthead"><span class="avatar">${esc(initials(u.name))}</span><div><h3>${esc(u.name)}</h3><span class="badge ${isTech()?'violet':'blue'}"><i class="bd"></i>${roleLabel(true)}</span></div></div><div class="info"><span class="muted">${icon('user')}${tr('الاسم')}</span><strong>${esc(u.name)}</strong></div><div class="info"><span class="muted">${icon('shield')}${tr('نوع الحساب')}</span><span>${roleLabel(true)}</span></div><div class="info"><span class="muted">${icon('note')}${tr('البريد')}</span><span dir="ltr">${esc(u.email)}</span></div>${u.department?`<div class="info"><span class="muted">${icon('building')}${tr('القسم أو الجهة')}</span><span>${esc(u.department)}</span></div>`:''}${u.specialty?`<div class="info"><span class="muted">${icon('wrench')}${tr('التخصص')}</span><span>${esc(tr(u.specialty))}</span></div>`:''}<div class="info"><span class="muted">${icon('globe')}${tr('لغة الواجهة')}</span><button class="btn secondary sm" onclick="toggleLang()">${lang==='en'?'العربية':'English'}</button></div>${liveProfile.technician_status==='pending'?`<p class="notice amber sectionspace">${icon('clock')}<span>${tr('طلب الفني بانتظار الاعتماد.')}</span></p>`:''}<div class="actions"><button class="btn danger" onclick="logout()">${icon('logout')}${tr('تسجيل الخروج')}</button></div>`)}
async function logout(){const r=await authClient.auth.signOut();if(r.error)return toast(authMessage(r.error),'error');currentSession=null;liveProfile=null;db=seed();loadVersion++;afterAuth=null;closeModal();page='dashboard';render();toast(tr('تم تسجيل الخروج.'),'info')}
function openRecovery(){modal(tr('استعادة كلمة المرور'),`<form onsubmit="sendRecovery(event)"><label class="fieldlabel" for="recoveryEmail">${tr('البريد الإلكتروني')}</label><input id="recoveryEmail" type="email" required dir="ltr"><p class="authnote sectionspace">${icon('info')}${tr('سنرسل رابط استعادة كلمة المرور إذا كان البريد مسجلًا.')}</p><div class="actions"><button type="button" class="btn secondary" onclick="showAuth()">${tr('رجوع')}</button><button class="btn" type="submit">${tr('إرسال الرابط')}</button></div></form>`)}
async function sendRecovery(e){e.preventDefault();if(!authClient)return;const result=await authClient.auth.resetPasswordForEmail(document.getElementById('recoveryEmail').value.trim(),{redirectTo:location.origin+'/'});if(result.error)return toast(authMessage(result.error),'error');closeModal();toast(tr('إذا كان البريد مسجّلًا، ستصلك رسالة الاستعادة.'),'info')}
function showPasswordUpdate(){modal(tr('تعيين كلمة مرور جديدة'),`<form onsubmit="updatePassword(event)"><label class="fieldlabel" for="nextPassword">${tr('كلمة المرور الجديدة')}</label>${pwField('nextPassword','new-password')}<label class="fieldlabel sectionspace" for="confirmNextPassword">${tr('تأكيد كلمة المرور')}</label>${pwField('confirmNextPassword','new-password')}<div class="actions"><button class="btn" type="submit">${tr('حفظ كلمة المرور')}</button></div></form>`)}
async function updatePassword(e){e.preventDefault();const p=document.getElementById('nextPassword').value;if(p!==document.getElementById('confirmNextPassword').value)return toast(tr('كلمتا المرور غير متطابقتين.'),'error');const r=await authClient.auth.updateUser({password:p});if(r.error)return toast(authMessage(r.error),'error');closeModal();toast(tr('تم تحديث كلمة المرور.'))}
function setupInteractions(){
  applyLanguage();
  setupPaletteComparison();
  try{const saved=localStorage.getItem('mirsad-theme');document.documentElement.dataset.theme=saved||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{document.documentElement.dataset.theme='light'}
  const d=document.getElementById('modal');
  d.addEventListener('cancel',e=>{e.preventDefault();closeModal()});
  d.addEventListener('click',e=>{if(e.target===d)closeModal()});
  document.addEventListener('pointerdown',e=>{const b=e.target.closest('.btn,.iconbtn,.rolebtn');if(!b||b.disabled||reducedMotion())return;const r=b.getBoundingClientRect(),s=Math.max(r.width,r.height)*2.2,el=document.createElement('span');el.className='ripple';el.style.cssText=`width:${s}px;height:${s}px;left:${e.clientX-r.left-s/2}px;top:${e.clientY-r.top-s/2}px`;b.appendChild(el);setTimeout(()=>el.remove(),700)});
  const top=document.getElementById('topbar');addEventListener('scroll',()=>top.classList.toggle('scrolled',scrollY>8),{passive:true});
  addEventListener('resize',moveIndicator);
  addEventListener('popstate',()=>{if(!routeApplied)return;const r=parseRoute(location.hash);if(r)applyRoute(r)});
  let gPressed=0;
  document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')||document.activeElement?.isContentEditable;if(typing||d.open)return;const k=e.key.toLowerCase();
    if(e.key==='/'){const s=document.getElementById('search');if(s){e.preventDefault();s.focus()}else if(currentUser()){e.preventDefault();go('tickets');setTimeout(()=>document.getElementById('search')?.focus(),50)}return}
    if(e.key==='?'){e.preventDefault();return showShortcuts()}
    if(gPressed&&Date.now()-gPressed<1200){gPressed=0;if(k==='d')return go('dashboard');if(k==='t')return go('tickets');if(k==='a'&&isTech())return go('activity');if(k==='h'&&isTech())return go('handovers');return}
    if(k==='g'){gPressed=Date.now();return}
    if(k==='n'&&serviceConfig?.ready){e.preventDefault();return openNew()}
    if(k==='l'){e.preventDefault();return toggleLang()}
  });
}
async function boot(){try{initialRoute=parseRoute(location.hash)}catch{}setupInteractions();render();try{const r=await fetch('/api/config',{cache:'no-store'});if(!r.ok)throw Error();serviceConfig=await r.json();render();if(!serviceConfig.ready){finishRoute();return}authClient=window.MirsadCreateClient(serviceConfig.supabaseUrl,serviceConfig.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const initial=await authClient.auth.getSession();currentSession=initial.data.session;await refreshWorkspace(false);authClient.auth.onAuthStateChange((event,session)=>{currentSession=session;if(event==='PASSWORD_RECOVERY'){setTimeout(showPasswordUpdate,0);return}if(['SIGNED_OUT','TOKEN_REFRESHED','SIGNED_IN','USER_UPDATED'].includes(event))setTimeout(()=>{if(!document.getElementById('modal').open&&!busy)refreshWorkspace(false)},0)});setInterval(()=>{if(currentSession&&document.visibilityState==='visible')refreshNotifications()},15000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&currentSession)refreshNotifications()});setInterval(()=>{if(currentSession&&!busy&&!document.getElementById('modal').open&&!['handover'].includes(page)&&document.visibilityState==='visible')refreshWorkspace(false)},30000)}catch{workspaceError=tr('تعذّر التحقق من اتصال الخدمات. أعد تحميل الصفحة.');serviceConfig={ready:false,aiReady:false};finishRoute();render()}}
boot();

function needsPriorityReview(t){return ['needs_review','failed'].includes(t.priorityState)||(t.priorityState==='processing'&&Date.parse(t.aiStartedAt)<Date.now()-60000)}
function priorityPanel(t){const review=needsPriorityReview(t);const source=tr(t.priorityState==='ready'?(t.prioritySource==='technician'?'حددها فني معتمد':'حددها الذكاء الاصطناعي'):(review?'بانتظار مراجعة فني معتمد. المستخدم لا يحدد الأولوية.':'يجري تحليل وصف المشكلة وتأثيرها على العمل.'));return `<div class="prioritybox sectionspace"><div class="pb-head"><div class="pb-title"><span class="chip">${icon(t.prioritySource==='technician'&&t.priorityState==='ready'?'user':'spark')}</span>${tr('أولوية البلاغ')}</div>${badge(t.priority)}</div><p class="priorityreason"><strong>${source}</strong></p><p class="priorityreason">${esc(tr(t.priorityReason||''))}</p>${t.questions?.length?`<div class="sectionspace"><strong>${tr('معلومات تساعد على التقييم')}</strong><ul>${t.questions.map(q=>`<li><bdi>${esc(q)}</bdi></li>`).join('')}</ul><small>${tr('أضف الإجابات في ملاحظة على البلاغ، ثم أعد التحليل أو انتظر مراجعة الفني.')}</small></div>`:''}${(review&&isTech())||t.priorityState!=='ready'?`<div class="actions">${t.priorityState!=='ready'?`<button class="btn secondary sm" onclick="retryClassification(${t.id})">${icon('refresh')}${tr('إعادة التحليل')}</button>`:''}${review&&isTech()?`<button class="btn sm" onclick="openPriorityReview(${t.id})">${tr('تحديد الأولوية بواسطة الفني')}</button>`:''}</div>`:''}</div>`}
function openPriorityReview(id){const t=db.tickets.find(t=>t.id===id);if(!isTech()||!t||!needsPriorityReview(t))return toast(tr('هذه العملية متاحة للفنيين المعتمدين عند تعذّر التصنيف فقط.'),'info');modal(tr('مراجعة أولوية البلاغ'),`<form onsubmit="submitPriorityReview(event,${id})"><p class="description">${tr('راجع الوصف وتأثير العطل والملاحظات قبل تحديد الأولوية. سيُحفظ اسمك وسبب القرار في سجل البلاغ.')}</p><div class="fieldgroup sectionspace"><label class="fieldlabel" for="reviewPriority">${tr('الأولوية')}</label><select id="reviewPriority" required><option value="">${tr('اختر بعد مراجعة المشكلة')}</option><option value="high">${tr('عالية — خطر أو توقف مؤثر وواسع')}</option><option value="medium">${tr('متوسطة — تعطّل تشغيلي محدود')}</option><option value="low">${tr('منخفضة — طلب غير معطّل للعمل')}</option></select></div><div class="fieldgroup"><label class="fieldlabel" for="reviewPriorityReason">${tr('سبب القرار وتأثير المشكلة')} *</label><textarea id="reviewPriorityReason" required minlength="5" maxlength="800" placeholder="${esc(tr('من المتأثر؟ هل توقف العمل؟ هل يوجد بديل؟'))}"></textarea></div><p class="error" id="priorityReviewError"></p><div class="actions"><button type="button" class="btn secondary" onclick="closeModal()">${tr('إلغاء')}</button><button type="submit" class="btn">${tr('حفظ الأولوية وتوثيق القرار')}</button></div></form>`)}
async function submitPriorityReview(e,id){e.preventDefault();const priority=document.getElementById('reviewPriority').value,reason=document.getElementById('reviewPriorityReason').value.trim();if(!priority||reason.length<5)return;await mutation(`tickets/${id}/priority`,{priority,reason},tr('تم حفظ أولوية الفني وتوثيق سبب القرار.'),()=>closeModal())}

function setupPaletteComparison(){
 const q=new URLSearchParams(location.search),petrol=q.get('palette')!=='purple';
 document.documentElement.dataset.palette=petrol?'petrol':'purple';
 if(!petrol){const style=document.createElement('link');style.rel='stylesheet';style.href='/palette-purple.css?v=1';style.id='palette-stylesheet';document.head.appendChild(style);const icon=document.querySelector('link[rel="icon"]');if(icon)icon.href='/favicon-purple.svg'}
 const bar=document.getElementById('paletteCompare');
 if(bar&&q.get('compare')==='1'){bar.hidden=false;bar.innerHTML='<strong>'+tr('مقارنة ألوان مِرصاد')+'</strong><nav class="palette-choices" aria-label="'+tr('مقارنة الألوان')+'"><a href="?palette=purple&compare=1" '+(!petrol?'aria-current="page"':'')+'><span class="palette-swatch" style="--swatch:#4B3FD3"></span>'+tr('البنفسجي الحالي')+'</a><a href="?palette=petrol&compare=1" '+(petrol?'aria-current="page"':'')+'><span class="palette-swatch" style="--swatch:#237A68"></span>'+tr('بترولي · نعناعي · ذهبي')+'</a></nav>'}
}
